        private static System.ServiceModel.EndpointAddress GetEndpointAddress(string endPoint)
        {
            if (string.IsNullOrEmpty(endPoint))
                throw new InvalidOperationException($"End point can not be empty. Check Appsettings.json");
             
            return new System.ServiceModel.EndpointAddress(endPoint);

        }
